  "inlineSchema": "// Ini adalah schema database untuk Gampang Toko Cloud (Fokus: POS)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================\n// 1. CABANG & LOKASI\n// ============================================\nmodel Cabang {\n  id         Int      @id @default(autoincrement())\n  kodeCabang String   @unique @db.VarChar(10)\n  namaCabang String   @db.VarChar(100)\n  status     Int      @default(1)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  lokasi    Lokasi[]\n  pengguna  Pengguna[]\n  penjualan Penjualan[]\n}\n\nmodel Lokasi {\n  id         Int      @id @default(autoincrement())\n  idCabang   Int\n  namaLokasi String   @db.VarChar(100)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  cabang    Cabang      @relation(fields: [idCabang], references: [id])\n  penjualan Penjualan[]\n}\n\n// ============================================\n// 2. PENGGUNA (KASIR/ADMIN)\n// ============================================\nmodel Pengguna {\n  id          Int      @id @default(autoincrement())\n  idCabang    Int\n  usernm      String   @unique @db.VarChar(30)\n  namaLengkap String   @db.VarChar(100)\n  passwd      String   @db.VarChar(255) // Password akan di-hash\n  status      Int      @default(1)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  cabang    Cabang      @relation(fields: [idCabang], references: [id])\n  penjualan Penjualan[]\n}\n\n// ============================================\n// 3. BARANG / PRODUK\n// ============================================\nmodel Barang {\n  id         Int      @id @default(autoincrement())\n  kodeBarang String   @unique @db.VarChar(30)\n  namaBarang String   @db.VarChar(200)\n  barcode    String?  @db.VarChar(50)\n  hargaJual  Decimal  @default(0) @db.Decimal(18, 2)\n  hpp        Decimal  @default(0) @db.Decimal(18, 2)\n  stok       Float    @default(0)\n  status     Int      @default(1)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  detailPenjualan DetailPenjualan[]\n\n  @@index([barcode])\n  @@index([namaBarang])\n}\n\n// ============================================\n// 4. TRANSAKSI PENJUALAN (POS)\n// ============================================\nmodel Penjualan {\n  id        Int      @id @default(autoincrement())\n  idCabang  Int\n  idLokasi  Int\n  idKasir   Int\n  nomorRef  String   @db.VarChar(30)\n  tanggal   DateTime @default(now())\n  total     Decimal  @db.Decimal(18, 2)\n  bayar     Decimal  @db.Decimal(18, 2)\n  kembalian Decimal  @db.Decimal(18, 2)\n  status    Int      @default(1) // 1 = Sukses, 0 = Batal\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  cabang Cabang            @relation(fields: [idCabang], references: [id])\n  lokasi Lokasi            @relation(fields: [idLokasi], references: [id])\n  kasir  Pengguna          @relation(fields: [idKasir], references: [id])\n  detail DetailPenjualan[]\n\n  @@index([tanggal])\n  @@index([nomorRef])\n}\n\nmodel DetailPenjualan {\n  id          Int     @id @default(autoincrement())\n  idPenjualan Int\n  idBarang    Int\n  itemNo      Int\n  qty         Float\n  hargaJual   Decimal @db.Decimal(18, 2)\n  total       Decimal @db.Decimal(18, 2)\n\n  penjualan Penjualan @relation(fields: [idPenjualan], references: [id], onDelete: Cascade)\n  barang    Barang    @relation(fields: [idBarang], references: [id])\n\n  @@unique([idPenjualan, itemNo])\n}\n",
